\section{Algorithm}
\begin{algorithm}
\caption{Score computation}
\label{alg:score}
\begin{algorithmic}[1]
\Require A graph $G = (V, E)$ with nodes $v \in V$
\Ensure Updated scores $\mathrm{score}[v]$ for all $v \in V$
\For{each node $v \in V$}
    \State update $\mathrm{score}[v]$
\EndFor
\State \Return scores
\end{algorithmic}
\end{algorithm}
